static HANDLE g_complete = nullptr;

static void CALLBACK QueryComplete(PVOID context, PDNS_QUERY_RESULT result) {
    PDNS_RECORD records = result->pQueryRecords;
    if (result->QueryStatus == ERROR_SUCCESS && records != nullptr) {
        printf("Address: %s\n", inet_ntoa(records->Data.A.IpAddress));
        DnsRecordListFree(records, DnsFreeRecordList);
    }
    SetEvent(static_cast<HANDLE>(context));
}

int main() {
    g_complete = CreateEventW(nullptr, TRUE, FALSE, nullptr);
    if (g_complete == nullptr) {
        return 1;
    }

    DNS_QUERY_REQUEST request = {};
    request.Version = DNS_QUERY_REQUEST_VERSION1;
    request.QueryName = L"localhost";
    request.QueryType = DNS_TYPE_A;
    request.QueryOptions = DNS_QUERY_STANDARD;

    DNS_QUERY_RESULT result = {};
    result.Version = DNS_QUERY_RESULT_VERSION1;

    DNS_STATUS status = DnsQueryEx(&request, &result, nullptr);
    if (status == DNS_REQUEST_PENDING) {
        WaitForSingleObject(g_complete, 5000);
    }

    CloseHandle(g_complete);
    return 0;
}

