#include <winsock2.h>
#include <ws2tcpip.h>
#include <stdio.h>

#pragma comment(lib, "ws2_32.lib")

int main() {
    WSADATA data = {};
    WSAStartup(MAKEWORD(2, 2), &data);

    SOCKET listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    sockaddr_in address = {};
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    address.sin_port = 0;
    bind(listener, reinterpret_cast<sockaddr*>(&address), sizeof(address));
    listen(listener, SOMAXCONN);
    int length = sizeof(address);
    getsockname(listener, reinterpret_cast<sockaddr*>(&address), &length);

    SOCKET client = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    connect(client, reinterpret_cast<sockaddr*>(&address), sizeof(address));
    SOCKET server = accept(listener, nullptr, nullptr);
    send(client, "example", 7, 0);

    u_long available = 0;
    DWORD returned = 0;
    WSAIoctl(server, FIONREAD, nullptr, 0, &available, sizeof(available),
        &returned, nullptr, nullptr);
    printf("Available bytes: %lu\n", available);

    closesocket(server);
    closesocket(client);
    closesocket(listener);
    WSACleanup();
    return 0;
}

#include <winsock2.h>
#include <ws2tcpip.h>
#include <stdio.h>

#pragma comment(lib, "ws2_32.lib")

int main() {
    WSADATA data = {};
    if (WSAStartup(MAKEWORD(2, 2), &data) != 0) {
        return 1;
    }

    SOCKET sock = WSASocketA(AF_INET, SOCK_STREAM, IPPROTO_TCP, nullptr, 0, 0);
    if (sock != INVALID_SOCKET) {
        closesocket(sock);
    }

    WSACleanup();
    return 0;
}

#include <winsock2.h>
#include <ws2tcpip.h>
#include <stdio.h>

#pragma comment(lib, "ws2_32.lib")

int main() {
    WSADATA data = {};
    int result = WSAStartup(MAKEWORD(2, 2), &data);
    if (result != 0) {
        printf("WSAStartup failed: %d\n", result);
        return 1;
    }

    printf("Winsock %u.%u\n", LOBYTE(data.wVersion), HIBYTE(data.wVersion));
    WSACleanup();
    return 0;
}
